insert into jp_grammar (id, level, grammar_pattern, meaning_vi, memory_hint_vi, connection, usage, register, notes, common_mistake, similar_patterns, difference_note, source_page, source_text, source_type, review_status) values ('f4928948-356a-4b7c-988c-16ba36f44e62', 'N2', '普通形(Aな／Aなである／Nの／Nである) ＋ 一方(で)', 'Ngược lại với.../Một mặt thì.../Mặt khác... (2 mặt/khía cạnh khác nhau của cùng 1 sự việc)', NULL, '普通形(Aな／Aなである／Nの／Nである) ＋ 一方(で)', 'Nêu 2 mặt/khía cạnh khác nhau (có thể trái ngược hoặc song song) của cùng 1 chủ thể', NULL, NULL, NULL, '{}', NULL, 73, '普通形(Aな／Aなである／Nの／Nである) ＋ 一方(で)', 'pdf', 'ok')
insert into jp_grammar (id, level, grammar_pattern, meaning_vi, memory_hint_vi, connection, usage, register, notes, common_mistake, similar_patterns, difference_note, source_page, source_text, source_type, review_status) values ('b5c41cc0-91cc-4d55-95ef-280768f037d7', 'N2', 'Vる ＋ 一方だ／ばかりだ', 'Càng ngày càng.../Có xu hướng... (1 chiều hướng biến đổi liên tục, thường là tiêu cực)', NULL, 'Vる ＋ 一方だ／ばかりだ', 'Diễn tả 1 xu hướng biến đổi liên tục theo 1 chiều duy nhất, thường mang sắc thái tiêu cực', NULL, NULL, NULL, '{}', NULL, 73, 'Vる ＋ 一方だ／ばかりだ', 'pdf', 'ok')
insert into jp_grammar (id, level, grammar_pattern, meaning_vi, memory_hint_vi, connection, usage, register, notes, common_mistake, similar_patterns, difference_note, source_page, source_text, source_type, review_status) values ('a5e7f500-de90-4e4c-948c-163098ddc847', 'N2', 'V(ます) ＋ つつある', 'Đang dần.../Đang ngày càng... (1 sự thay đổi đang diễn ra, tiến triển dần)', NULL, 'Vます ＋ つつある', 'Diễn tả 1 sự thay đổi/xu hướng đang diễn ra dần dần ở thời điểm hiện tại', NULL, NULL, NULL, '{}', NULL, 73, 'V(ます) ＋ つつある', 'pdf', 'ok')
insert into jp_grammar (id, level, grammar_pattern, meaning_vi, memory_hint_vi, connection, usage, register, notes, common_mistake, similar_patterns, difference_note, source_page, source_text, source_type, review_status) values ('85034091-0df3-4b10-90c1-be88b65affa3', 'N2', 'Vない ＋ ざるをえない', 'Buộc phải, đành phải~ (せざるを得ない) (không còn lựa chọn nào khác)', NULL, 'Vない(bỏ ない) ＋ ざるをえない', 'Diễn tả việc buộc phải làm 1 điều gì đó dù không muốn, vì không còn lựa chọn nào khác', NULL, NULL, NULL, '{}', NULL, 73, 'Vない ＋ ざるをえない', 'pdf', 'ok')
insert into jp_grammar (id, level, grammar_pattern, meaning_vi, memory_hint_vi, connection, usage, register, notes, common_mistake, similar_patterns, difference_note, source_page, source_text, source_type, review_status) values ('87e0df92-281a-43f7-aa68-4b33b3373aa0', 'N2', 'Vる／Vない ＋ わけにはいかない', 'Không thể nào mà lại.../Buộc phải... (không thể làm/không làm vì lý do đạo đức, xã hội)', NULL, 'Vる／Vない ＋ わけにはいかない', 'Diễn tả việc không thể làm/không làm 1 điều gì đó vì lý do đạo đức, trách nhiệm, xã hội', NULL, NULL, NULL, '{}', NULL, 73, 'Vる／Vない ＋ わけにはいかない', 'pdf', 'ok')
insert into jp_grammar (id, level, grammar_pattern, meaning_vi, memory_hint_vi, connection, usage, register, notes, common_mistake, similar_patterns, difference_note, source_page, source_text, source_type, review_status) values ('141bce1c-c7e4-4903-bf7f-5f2616db9c8f', 'N2', 'Vる ＋ よりほかない', 'Chỉ còn cách... (không còn lựa chọn nào khác ngoài phương án đã nêu)', NULL, 'Vる ＋ よりほか(は)ない', 'Diễn tả việc chỉ còn duy nhất 1 phương án/cách giải quyết trong tình huống hiện tại', NULL, NULL, NULL, '{}', NULL, 73, 'Vる ＋ よりほかない', 'pdf', 'ok')
insert into jp_grammar (id, level, grammar_pattern, meaning_vi, memory_hint_vi, connection, usage, register, notes, common_mistake, similar_patterns, difference_note, source_page, source_text, source_type, review_status) values ('24e26fcb-0d14-40f8-b869-c71afae5a898', 'N2', 'V意向形 ＋ ではないか', '(Kêu gọi) chúng ta hãy... (đề xuất/kêu gọi cùng làm 1 việc)', NULL, 'V意向形 ＋ ではないか', 'Đưa ra lời đề xuất/kêu gọi mọi người cùng làm 1 việc gì đó', NULL, NULL, NULL, '{}', NULL, 73, 'V意向形 ＋ ではないか', 'pdf', 'ok')
insert into jp_grammar (id, level, grammar_pattern, meaning_vi, memory_hint_vi, connection, usage, register, notes, common_mistake, similar_patterns, difference_note, source_page, source_text, source_type, review_status) values ('3055848f-a9fe-4f92-b8cf-67c44078ef41', 'N2', 'N ＋ にほかならない', 'Chắc chắn là.../Chỉ có thể là.../Không gì khác ngoài... (khẳng định mạnh mẽ, loại trừ khả năng khác)', NULL, 'N ＋ にほかならない', 'Khẳng định mạnh mẽ rằng nguyên nhân/bản chất của 1 sự việc chỉ có thể là điều đã nêu, không gì khác', NULL, NULL, NULL, '{}', NULL, 73, 'N ＋ にほかならない', 'pdf', 'ok')
insert into jp_grammar (id, level, grammar_pattern, meaning_vi, memory_hint_vi, connection, usage, register, notes, common_mistake, similar_patterns, difference_note, source_page, source_text, source_type, review_status) values ('2ea53d9b-b83d-454b-a50a-c05e8615571e', 'N2', 'Vて ＋ はいられない', 'Không thể nào mà...thêm nữa (hoàn cảnh không cho phép tiếp tục 1 hành động)', NULL, 'Vて ＋ はいられない', 'Diễn tả việc không thể tiếp tục 1 hành động/trạng thái vì hoàn cảnh không cho phép', NULL, NULL, NULL, '{}', NULL, 73, 'Vて ＋ はいられない', 'pdf', 'ok')
insert into jp_grammar_examples (grammar_id, usage_id, example_no, example_type, example_jp, example_vi, cloze_jp, answer, source_type) values ('f4928948-356a-4b7c-988c-16ba36f44e62', NULL, 1, 'standard', '彼は音楽家である一方、画家としても活躍している。', 'Anh ấy hoạt động trong vai trò là một nhạc sĩ, mặt khác cũng hoạt động với tư cách là họa sĩ.', '彼は音楽家である＿＿＿、画家としても活躍している。', '一方', 'pdf');
insert into jp_grammar_examples (grammar_id, usage_id, example_no, example_type, example_jp, example_vi, cloze_jp, answer, source_type) values ('f4928948-356a-4b7c-988c-16ba36f44e62', NULL, 2, 'daily', 'この薬はよく効く一方で、副作用も強い。', 'Loại thuốc này rất hiệu quả, mặt khác tác dụng phụ cũng mạnh.', 'この薬はよく効く＿＿＿、副作用も強い。', '一方で', 'generated');
insert into jp_grammar_examples (grammar_id, usage_id, example_no, example_type, example_jp, example_vi, cloze_jp, answer, source_type) values ('f4928948-356a-4b7c-988c-16ba36f44e62', NULL, 3, 'daily', '都会は便利である一方、生活費が高い。', 'Thành phố tiện lợi, nhưng mặt khác chi phí sinh hoạt lại cao.', '都会は便利である＿＿＿、生活費が高い。', '一方', 'generated');
insert into jp_grammar_examples (grammar_id, usage_id, example_no, example_type, example_jp, example_vi, cloze_jp, answer, source_type) values ('b5c41cc0-91cc-4d55-95ef-280768f037d7', NULL, 1, 'standard', '薬を飲み休んでいるが、病状は悪くなるばかりだ。', 'Mặc dù tôi đã uống thuốc và nghỉ ngơi nhưng tình trạng bệnh lại xấu đi.', '薬を飲み休んでいるが、病状は悪くなる＿＿＿。', 'ばかりだ', 'pdf');
insert into jp_grammar_examples (grammar_id, usage_id, example_no, example_type, example_jp, example_vi, cloze_jp, answer, source_type) values ('b5c41cc0-91cc-4d55-95ef-280768f037d7', NULL, 2, 'daily', '物価は上がる一方だ。', 'Vật giá cứ tăng lên mãi.', '物価は上がる＿＿＿。', '一方だ', 'generated');
insert into jp_grammar_examples (grammar_id, usage_id, example_no, example_type, example_jp, example_vi, cloze_jp, answer, source_type) values ('b5c41cc0-91cc-4d55-95ef-280768f037d7', NULL, 3, 'daily', '彼との関係は悪化する一方だ。', 'Mối quan hệ với anh ấy càng ngày càng xấu đi.', '彼との関係は悪化する＿＿＿。', '一方だ', 'generated');
insert into jp_grammar_examples (grammar_id, usage_id, example_no, example_type, example_jp, example_vi, cloze_jp, answer, source_type) values ('a5e7f500-de90-4e4c-948c-163098ddc847', NULL, 1, 'standard', '日本に観光に訪れる外国の方が、年々増えつつある。', 'Những người nước ngoài đến Nhật Bản du lịch đang tăng lên hàng năm.', '日本に観光に訪れる外国の方が、年々増え＿＿＿。', 'つつある', 'pdf');
insert into jp_grammar_examples (grammar_id, usage_id, example_no, example_type, example_jp, example_vi, cloze_jp, answer, source_type) values ('a5e7f500-de90-4e4c-948c-163098ddc847', NULL, 2, 'daily', '環境問題への関心が高まりつつある。', 'Sự quan tâm đến vấn đề môi trường đang dần tăng lên.', '環境問題への関心が高まり＿＿＿。', 'つつある', 'generated');
insert into jp_grammar_examples (grammar_id, usage_id, example_no, example_type, example_jp, example_vi, cloze_jp, answer, source_type) values ('a5e7f500-de90-4e4c-948c-163098ddc847', NULL, 3, 'daily', 'その習慣は徐々に失われつつある。', 'Phong tục đó đang dần mất đi.', 'その習慣は徐々に失われ＿＿＿。', 'つつある', 'generated');
insert into jp_grammar_examples (grammar_id, usage_id, example_no, example_type, example_jp, example_vi, cloze_jp, answer, source_type) values ('85034091-0df3-4b10-90c1-be88b65affa3', NULL, 1, 'standard', '急な用事が入ったため、夜の飲み会は断らざるをえない。', 'Vì có việc gấp nên đành phải từ chối buổi nhậu đêm.', '急な用事が入ったため、夜の飲み会は断ら＿＿＿。', 'ざるをえない', 'pdf');
insert into jp_grammar_examples (grammar_id, usage_id, example_no, example_type, example_jp, example_vi, cloze_jp, answer, source_type) values ('85034091-0df3-4b10-90c1-be88b65affa3', NULL, 2, 'daily', '状況が状況だけに、計画を中止せざるをえない。', 'Vì tình hình như vậy nên đành phải hủy kế hoạch.', '状況が状況だけに、計画を中止＿＿＿。', 'せざるをえない', 'generated');
insert into jp_grammar_examples (grammar_id, usage_id, example_no, example_type, example_jp, example_vi, cloze_jp, answer, source_type) values ('85034091-0df3-4b10-90c1-be88b65affa3', NULL, 3, 'daily', '上司の命令だから、従わざるをえない。', 'Vì là lệnh của cấp trên nên đành phải tuân theo.', '上司の命令だから、従わ＿＿＿。', 'ざるをえない', 'generated');
insert into jp_grammar_examples (grammar_id, usage_id, example_no, example_type, example_jp, example_vi, cloze_jp, answer, source_type) values ('87e0df92-281a-43f7-aa68-4b33b3373aa0', NULL, 1, 'standard', 'テストが控えているから、勉強をしないわけにはいかない。', 'Vì kì thi đang đến sát gần nên đành phải học.', 'テストが控えているから、勉強をしない＿＿＿。', 'わけにはいかない', 'pdf');
insert into jp_grammar_examples (grammar_id, usage_id, example_no, example_type, example_jp, example_vi, cloze_jp, answer, source_type) values ('87e0df92-281a-43f7-aa68-4b33b3373aa0', NULL, 2, 'daily', '約束したから、行かないわけにはいかない。', 'Vì đã hứa rồi nên không thể không đi được.', '約束したから、行かない＿＿＿。', 'わけにはいかない', 'generated');
insert into jp_grammar_examples (grammar_id, usage_id, example_no, example_type, example_jp, example_vi, cloze_jp, answer, source_type) values ('87e0df92-281a-43f7-aa68-4b33b3373aa0', NULL, 3, 'daily', '会社の規則だから、守らないわけにはいかない。', 'Vì là quy định của công ty nên buộc phải tuân thủ.', '会社の規則だから、守らない＿＿＿。', 'わけにはいかない', 'generated');
insert into jp_grammar_examples (grammar_id, usage_id, example_no, example_type, example_jp, example_vi, cloze_jp, answer, source_type) values ('141bce1c-c7e4-4903-bf7f-5f2616db9c8f', NULL, 1, 'standard', '試験に合格したいなら死ぬ気で勉強するよりほかないよ。', 'Nếu muốn đỗ trong kì thi thì chỉ còn cách học hết mình thôi.', '試験に合格したいなら死ぬ気で勉強する＿＿＿よ。', 'よりほかない', 'pdf');
insert into jp_grammar_examples (grammar_id, usage_id, example_no, example_type, example_jp, example_vi, cloze_jp, answer, source_type) values ('141bce1c-c7e4-4903-bf7f-5f2616db9c8f', NULL, 2, 'daily', '道具がないので、手で作業するよりほかない。', 'Vì không có dụng cụ nên chỉ còn cách làm bằng tay thôi.', '道具がないので、手で作業する＿＿＿。', 'よりほかない', 'generated');
insert into jp_grammar_examples (grammar_id, usage_id, example_no, example_type, example_jp, example_vi, cloze_jp, answer, source_type) values ('141bce1c-c7e4-4903-bf7f-5f2616db9c8f', NULL, 3, 'daily', '彼に頼るよりほかに方法がない。', 'Không còn cách nào khác ngoài việc nhờ cậy anh ấy.', '彼に頼る＿＿＿に方法がない。', 'よりほか', 'generated');
insert into jp_grammar_examples (grammar_id, usage_id, example_no, example_type, example_jp, example_vi, cloze_jp, answer, source_type) values ('24e26fcb-0d14-40f8-b869-c71afae5a898', NULL, 1, 'standard', '今のままでは何も決まらない。一度じっくり話し合ってみようではないか。', 'Nếu cứ đà này thì sẽ chẳng quyết định được. Chúng ta hãy cùng nhau nói chuyện lại cẩn thận 1 lần nữa xem sao.', '一度じっくり話し合ってみ＿＿＿。', 'ようではないか', 'pdf');
insert into jp_grammar_examples (grammar_id, usage_id, example_no, example_type, example_jp, example_vi, cloze_jp, answer, source_type) values ('24e26fcb-0d14-40f8-b869-c71afae5a898', NULL, 2, 'daily', 'みんなで力を合わせて頑張ろうではないか。', 'Chúng ta hãy cùng nhau hợp sức cố gắng nào.', 'みんなで力を合わせて頑張ろ＿＿＿。', 'うではないか', 'generated');
insert into jp_grammar_examples (grammar_id, usage_id, example_no, example_type, example_jp, example_vi, cloze_jp, answer, source_type) values ('24e26fcb-0d14-40f8-b869-c71afae5a898', NULL, 3, 'daily', 'この問題について、もう一度考えてみようではないか。', 'Về vấn đề này, chúng ta hãy cùng suy nghĩ lại một lần nữa nhé.', 'この問題について、もう一度考えてみ＿＿＿。', 'ようではないか', 'generated');
insert into jp_grammar_examples (grammar_id, usage_id, example_no, example_type, example_jp, example_vi, cloze_jp, answer, source_type) values ('3055848f-a9fe-4f92-b8cf-67c44078ef41', NULL, 1, 'standard', 'JLPTに合格できたのは、彼の努力の成果にほかならない。', 'Việc có thể đỗ JLPT, không gì khác ngoài thành quả nỗ lực của anh ấy.', 'JLPTに合格できたのは、彼の努力の成果＿＿＿。', 'にほかならない', 'pdf');
insert into jp_grammar_examples (grammar_id, usage_id, example_no, example_type, example_jp, example_vi, cloze_jp, answer, source_type) values ('3055848f-a9fe-4f92-b8cf-67c44078ef41', NULL, 2, 'daily', '彼が成功したのは、努力の結果にほかならない。', 'Việc anh ấy thành công chỉ có thể là kết quả của sự nỗ lực.', '彼が成功したのは、努力の結果＿＿＿。', 'にほかならない', 'generated');
insert into jp_grammar_examples (grammar_id, usage_id, example_no, example_type, example_jp, example_vi, cloze_jp, answer, source_type) values ('3055848f-a9fe-4f92-b8cf-67c44078ef41', NULL, 3, 'daily', 'この事故は人為的なミスにほかならない。', 'Tai nạn này chắc chắn là do lỗi của con người.', 'この事故は人為的なミス＿＿＿。', 'にほかならない', 'generated');
insert into jp_grammar_examples (grammar_id, usage_id, example_no, example_type, example_jp, example_vi, cloze_jp, answer, source_type) values ('2ea53d9b-b83d-454b-a50a-c05e8615571e', NULL, 1, 'standard', '試験も近いので、遊んではいられません。', 'Vì kì thi tới gần rồi nên không thể nào mà chơi thêm được.', '試験も近いので、遊んで＿＿＿。', 'はいられません', 'pdf');
insert into jp_grammar_examples (grammar_id, usage_id, example_no, example_type, example_jp, example_vi, cloze_jp, answer, source_type) values ('2ea53d9b-b83d-454b-a50a-c05e8615571e', NULL, 2, 'daily', 'こんな状況で、じっとしてはいられない。', 'Trong tình huống thế này thì không thể nào ngồi yên được.', 'こんな状況で、じっとして＿＿＿。', 'はいられない', 'generated');
insert into jp_grammar_examples (grammar_id, usage_id, example_no, example_type, example_jp, example_vi, cloze_jp, answer, source_type) values ('2ea53d9b-b83d-454b-a50a-c05e8615571e', NULL, 3, 'daily', '彼の話を聞いて、黙ってはいられなかった。', 'Nghe câu chuyện của anh ấy, tôi không thể nào im lặng được.', '彼の話を聞いて、黙って＿＿＿。', 'はいられなかった', 'generated');
insert into jp_grammar_questions (grammar_id, usage_id, question_type, question_text, correct_answer, source_type) values ('f4928948-356a-4b7c-988c-16ba36f44e62', NULL, 'fill_blank', 'Điền vào chỗ trống: 彼は音楽家である＿＿＿、画家としても活躍している。', '一方', 'generated');
insert into jp_grammar_questions (grammar_id, usage_id, question_type, question_text, choice_1, choice_2, choice_3, choice_4, correct_answer, source_type) values ('f4928948-356a-4b7c-988c-16ba36f44e62', NULL, 'choose_meaning', 'Mẫu ngữ pháp "普通形(Aな／Aなである／Nの／Nである) ＋ 一方(で)" (usage này) có nghĩa là gì?', 'Ngược lại với.../Một mặt thì.../Mặt khác... (2 mặt/khía cạnh khác nhau của cùng 1 sự việc)', 'Buộc phải, đành phải~ (せざるを得ない) (không còn lựa chọn nào khác)', '(Kêu gọi) chúng ta hãy... (đề xuất/kêu gọi cùng làm 1 việc)', 'Càng ngày càng.../Có xu hướng... (1 chiều hướng biến đổi liên tục, thường là tiêu cực)', 'Ngược lại với.../Một mặt thì.../Mặt khác... (2 mặt/khía cạnh khác nhau của cùng 1 sự việc)', 'generated');
insert into jp_grammar_questions (grammar_id, usage_id, question_type, question_text, choice_1, choice_2, choice_3, choice_4, correct_answer, source_type) values ('f4928948-356a-4b7c-988c-16ba36f44e62', NULL, 'choose_connection', 'Cách nối nào tạo ra nghĩa: "Ngược lại với.../Một mặt thì.../Mặt khác... (2 mặt/khía cạnh khác nhau của cùng 1 sự việc)"?', 'Vて ＋ はいられない', 'V(ます) ＋ つつある', '普通形(Aな／Aなである／Nの／Nである) ＋ 一方(で)', 'Vる ＋ よりほかない', '普通形(Aな／Aなである／Nの／Nである) ＋ 一方(で)', 'generated');
